package com.example.starter.ili;

import java.math.BigDecimal;
import java.util.List;

/**
 * 缺陷对齐引擎：按绝对里程容差 ±0.5m（含边界）贪心匹配旧新两回合缺陷，
 * 一对多候选时取里程差最小者，每个缺陷最多出现在一个匹配对中。
 */
public final class MatchingEngine {

    /** 匹配容差（米），里程差绝对值小于等于该值即视为候选匹配。 */
    public static final BigDecimal TOLERANCE_M = new BigDecimal("0.5");

    private MatchingEngine() {
    }

    /** 参与匹配的缺陷读数。 */
    public record DefectInput(String defectRef, BigDecimal absMileageM, BigDecimal depthPct) {
    }

    /** 一个匹配对及其里程差绝对值（米）。 */
    public record MatchedPair(DefectInput oldDefect, DefectInput newDefect, BigDecimal mileageDiffM) {
    }

    /** 对齐结果：匹配对、新发现（仅新回合存在）、已消失（仅旧回合存在）。 */
    public record MatchResult(List<MatchedPair> pairs, List<DefectInput> newFindings,
            List<DefectInput> disappeared) {
    }

    /**
     * 对两个回合的缺陷读数做里程对齐。
     *
     * @param oldDefects 旧回合缺陷
     * @param newDefects 新回合缺陷
     * @return 对齐结果，未匹配的新回合缺陷记为新发现，未匹配的旧回合缺陷记为已消失
     */
    public static MatchResult match(List<DefectInput> oldDefects, List<DefectInput> newDefects) {
        throw new UnsupportedOperationException("待实现");
    }
}

package com.example.starter.ili;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * 缺陷分级策略：按深度年化增长率（百分点/年）分级。
 * 增长率 &lt; 5%/年为稳定，&ge; 5%/年为增长，&ge; 15%/年为严重。
 */
public final class GradePolicy {

    /** 增长分级阈值（百分点/年），达到或超过即为增长。 */
    public static final BigDecimal GROWING_THRESHOLD = new BigDecimal("5");

    /** 严重分级阈值（百分点/年），达到或超过即为严重。 */
    public static final BigDecimal SEVERE_THRESHOLD = new BigDecimal("15");

    /** 一年按 365 天折算年化增长率。 */
    public static final BigDecimal DAYS_PER_YEAR = new BigDecimal("365");

    private GradePolicy() {
    }

    /** 分级结果。 */
    public enum Grade {
        STABLE, GROWING, SEVERE
    }

    /**
     * 计算深度年化增长率（百分点/年），保留 4 位小数（HALF_UP）。
     *
     * @param oldDepthPct 旧回合深度（壁厚百分比）
     * @param newDepthPct 新回合深度（壁厚百分比）
     * @param oldDate     旧回合检测日期
     * @param newDate     新回合检测日期，必须晚于旧回合
     */
    public static BigDecimal annualGrowthRate(BigDecimal oldDepthPct, BigDecimal newDepthPct,
            LocalDate oldDate, LocalDate newDate) {
        throw new UnsupportedOperationException("待实现");
    }

    /**
     * 按年化增长率分级：&lt;5 稳定，&ge;5 增长，&ge;15 严重。
     */
    public static Grade grade(BigDecimal annualRatePctPerYear) {
        throw new UnsupportedOperationException("待实现");
    }
}

package com.example.starter.ili;

/**
 * 幂等指纹：对 requestId、管段、两回合标识与全部缺陷读数做规范化摘要（SHA-256）。
 * 缺陷清单按缺陷编号排序后参与摘要，数值经过去尾零规范化，保证同参同指纹。
 */
public final class Fingerprint {

    private Fingerprint() {
    }

    /**
     * 计算导入请求的规范化指纹（SHA-256 十六进制，64 字符）。
     */
    public static String of(Dtos.ImportAlignmentRequest request) {
