            String status = matchedRefs.contains(defect.defectRef()) ? MATCH_MATCHED : unmatchedStatus;
            long id = alignmentRepository.insertReading(batchId, runId, defect.defectRef(),
                    defect.absMileageM(), defect.depthPct(), status);
